  Future<GScaleRpsBatchResponse> _startRsBatchFromSelection({
    required double grossQtyKg,
  }) async {
    final server = widget.server;
    if (widget.printTransport == PrintTransport.wifi && server == null) {
      throw Exception('Avval printer yoki tarozini tanlang');
    }
    final item = _selectedItem;
    if (item == null) {
      throw Exception('Mahsulot tanlang');
    }
    final widthMm = parsePositiveKg(_widthController.text);
    final micron = parsePositiveKg(_micronController.text);
    if (item.requiresDimensions && widthMm == null) {
      throw Exception("Material enini mm da to'g'ri kiriting");
    }
    if (item.requiresDimensions && micron == null) {
      throw Exception("Material mikronini to'g'ri kiriting");
    }
    final warehouse = _selectedPrintWarehouse();
    if (warehouse == null || warehouse.trim().isEmpty) {
      throw Exception('Ombor tanlang');
    }
    if (!await _materialWarehouseAllowed(warehouse)) {
      throw Exception('Bu ombor sizga biriktirilmagan');
    }
    final tareKg =
        _babinaEnabled ? parsePositiveKg(_babinaWeightController.text) : 0.0;
    if (_babinaEnabled && tareKg == null) {
      throw Exception("Babina og'irligini kg da to'g'ri kiriting");
    }
    final offlinePrinter = widget.printTransport.isOffline
        ? widget.offlinePrinter ?? await PrintService.detectOfflinePrinter()
        : null;
    final bluetoothPrinter =
        widget.printTransport.isBluetooth ? widget.bluetoothPrinter : null;
    if (widget.printTransport.isBluetooth && bluetoothPrinter == null) {
      throw Exception('XP-P323B Bluetooth printer tanlanmagan');
    }
    final printer = offlinePrinter?.printer ??
        bluetoothPrinter?.printer ??
        normalizePrinterChoice(_batchPrinter);
    final printMode = offlinePrinter?.printMode ??
        bluetoothPrinter?.printMode ??
        (printer == 'godex'
            ? 'label'
            : (_batchPrintMode == 'label' ? 'label' : 'rfid'));
    final api = MobileApi.instance;
    final driverUrl = widget.printTransport.isLocal
        ? offlineUsbDriverUrl
        : driverUrlForRs(server!);
    final started = await api
        .gscaleRpsBatchStart(
          buildGScaleRpsBatchStartRequest(
            driverUrl: driverUrl,
            item: item,
            warehouse: warehouse,
            printer: printer,
            printMode: printMode,
            quantitySource: normalizeQuantitySource(_quantitySource),
            manualQtyKg: normalizeQuantitySource(_quantitySource) == 'manual'
                ? grossQtyKg
                : 0,
            tareEnabled: _babinaEnabled,
            tareKg: tareKg ?? 0,
            widthMm: item.requiresDimensions ? widthMm : null,
            micron: item.requiresDimensions ? micron : null,
          ),
        )
        .timeout(const Duration(seconds: 15));
    if (mounted) {
      setState(() {
        _applyRsBatchSession(started.batch);
        _lastAutoBatchPrintKey = '';
      });
    }
    return started;
  }

